/* Unified local campaign and tower scorebook for the prototype. Read-only. */
(()=>{
 const E=(t,c,text)=>{const e=document.createElement(t);if(c)e.className=c;if(text!==undefined)e.textContent=text;return e};const num=n=>Number.isFinite(+n)?Math.max(0,+n):0,format=n=>Math.round(num(n)).toLocaleString('pt-BR');
 function read(key,real=false){try{const raw=real?window.OAK_REAL_STORAGE_READ?.(key):localStorage.getItem(key),data=JSON.parse(raw||'[]');return Array.isArray(data)?data:[]}catch{return []}}
 function records(key){const all=[...read(key,true),...read(key)],unique=new Map();for(const r of all){if(!r||typeof r!=='object')continue;unique.set(r.id||[r.ts||r.at,r.score,r.floors,r.diff].join(':'),r)}return [...unique.values()]}
 function campaign(){const saved=records('ptft_campaign_scores_v1');return saved.length?saved:records('ptft_runs_v2')}
 const overlay=E('div','stream-scores-overlay');overlay.hidden=true;const panel=E('section','stream-scorebook');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','stream-score-title');overlay.append(panel);document.body.append(overlay);let mode='campaign',difficulty='normal',order='score',returnFocus=null,selected=null;
 const stamp=r=>num(r.ts||r.at),points=r=>Number.isFinite(+r.score)?num(r.score):Math.round(num(r.badges)*100+num(r.e4)*150+num(r.level)*10+num(r.gold)+num(r.hp)+num(r.wins)*25);
 function close(){overlay.hidden=true;returnFocus?.focus();if(!CFG.mute)SND.mback()}
 function open(requested){returnFocus=document.activeElement;mode=requested==='tower'?'tower':'campaign';difficulty=CFG.diff||'normal';order='score';selected=null;document.getElementById('scores')?.classList.remove('show');overlay.hidden=false;render();panel.querySelector('.stream-score-close').focus()}
 function render(){panel.replaceChildren();const head=E('header','stream-score-head'),title=E('div');title.append(E('small','','OAKCHESS / REGISTROS LOCAIS'));const h=E('h2','','Central de pontuações');h.id='stream-score-title';title.append(h,E('p','','Campanha e Torre. Cada jornada deixa sua marca.'));const x=E('button','stream-score-close','×');x.setAttribute('aria-label','Fechar pontuações');x.onclick=close;head.append(title,x);panel.append(head);
 const tabs=E('nav','stream-score-modes');tabs.setAttribute('aria-label','Modo de jogo');for(const [id,name,desc,img]of [['campaign','Campanha','O caminho até a Liga','assets/mode-art/campaign-meadow.png'],['tower','Torre dos Desafios','60 andares · 12 setores','assets/mode-art/tower-mewtwo.png']]){const b=E('button');b.style.setProperty('--mode-art','url("'+img+'")');b.setAttribute('aria-pressed',String(mode===id));b.append(E('strong','',name),E('small','',desc));b.onclick=()=>{mode=id;selected=null;render();SND.mnav()};tabs.append(b)}panel.append(tabs);
 let all=(mode==='tower'?records('oakchess_tower_sector1_v1_records').filter(r=>!r.preview):campaign().filter(r=>(r.mode||'campaign')==='campaign'&&(r.diff||r.last?.diff||'normal')===difficulty));
 all.sort((a,b)=>order==='recent'?stamp(b)-stamp(a):order==='floors'?num(b.floors)-num(a.floors)||points(b)-points(a):points(b)-points(a)||stamp(b)-stamp(a));
 const content=E('div','stream-score-content'),tools=E('div','stream-score-tools');if(mode==='campaign'){const diffs=E('div','stream-score-difficulties');for(const [id,name]of [['easy','Fácil'],['normal','Normal'],['hard','Difícil']]){const b=E('button','',name);b.setAttribute('aria-pressed',String(difficulty===id));b.onclick=()=>{difficulty=id;selected=null;render()};diffs.append(b)}tools.append(diffs)}else tools.append(E('span','stream-tower-record-note','Tentativas oficiais · prévias não entram no ranking'));
 const sort=E('select');sort.setAttribute('aria-label','Ordenar resultados');for(const [id,label]of [['score','Maior pontuação'],['recent','Mais recentes'],...(mode==='tower'?[['floors','Mais andares']]:[])]){const o=E('option','',label);o.value=id;sort.append(o)}sort.value=order;sort.onchange=()=>{order=sort.value;render()};tools.append(sort);content.append(tools);
 const best=[...all].sort((a,b)=>points(b)-points(a))[0],wins=all.filter(r=>mode==='tower'?r.won:r.win).length,summary=E('div','stream-score-summary');for(const [value,label]of [[best?format(points(best)):'—','RECORDE PESSOAL'],[String(all.length),'JORNADAS REGISTRADAS'],[String(wins),mode==='tower'?'TORRES CONCLUÍDAS':'VITÓRIAS'],[mode==='tower'?(all.length?Math.max(...all.map(r=>num(r.floors)))+' / 60':'—'):(all.length?Math.max(...all.map(r=>num(r.badges)))+' / 8':'—'),mode==='tower'?'MELHOR SUBIDA':'INSÍGNIAS']]){const box=E('div');box.append(E('strong','',value),E('small','',label));summary.append(box)}content.append(summary);
 const layout=E('div','stream-score-layout'),ranking=E('section','stream-score-ranking');ranking.append(E('h3','',mode==='tower'?'Classificação da Torre':'Classificação da campanha'));
 if(!all.length){const empty=E('div','stream-score-empty');empty.append(E('span','','◇'),E('h4','',mode==='tower'?'Sua primeira subida começa aqui':'Sua história ainda vai entrar neste quadro'),E('p','',mode==='tower'?'Finalize uma tentativa oficial da Torre. Pontos, andares e relíquias aparecerão aqui automaticamente.':'Finalize uma campanha nesta dificuldade para registrar seu resultado.'));ranking.append(empty)}else{const list=E('ol','stream-score-list');for(const [i,r]of all.slice(0,30).entries()){const row=E('li'),b=E('button');b.setAttribute('aria-pressed',String(selected===r));b.append(E('span','stream-score-rank',String(i+1).padStart(2,'0')));const text=E('span','stream-score-row-copy');text.append(E('strong','',(mode==='tower'?r.won:r.win)?(mode==='tower'?'Torre conquistada':'Campeão de Kanto'):(mode==='tower'?'Escalada da Torre':r.title||'Jornada por Kanto')),E('small','',(mode==='tower'?num(r.floors)+' / '+(r.total||60)+' andares':num(r.badges)+' / 8 insígnias')+' · '+(stamp(r)?new Date(stamp(r)).toLocaleDateString('pt-BR'):'Data não registrada')));b.append(text,E('strong','stream-score-value',format(points(r))));b.onclick=()=>{selected=r;render()};row.append(b);list.append(row)}ranking.append(list)}layout.append(ranking);
 const detail=E('aside','stream-score-detail'),record=selected||best;detail.append(E('small','',selected?'JORNADA SELECIONADA':'SEU MELHOR RESULTADO'));if(record){detail.append(E('strong','stream-score-detail-points',format(points(record))),E('span','stream-score-points-label','PONTOS'));const fields=mode==='tower'?[['Andares',num(record.floors)+' / '+(record.total||60)],['Setores completos',Math.floor(num(record.floors)/5)+' / 12'],['Derrotas',String(num(record.losses))],['Relíquias',String(Array.isArray(record.relics)?record.relics.length:0)],['Vida restante',String(num(record.hp))]]:[['Insígnias',num(record.badges)+' / 8'],['Elite 4',num(record.e4)+' / 4'],['Nível',String(num(record.level))],['Ouro',String(num(record.gold))],['Vida restante',String(num(record.hp))]];for(const [label,value]of fields){const row=E('div','stream-score-stat');row.append(E('span','',label),E('b','',value));detail.append(row)}if(mode==='tower'){const track=E('progress');track.max=60;track.value=num(record.floors);track.setAttribute('aria-label','Andares vencidos');detail.append(track,E('p','stream-score-formula','Pontos: andares × 100 + vida × 2 + relíquias × 15 − derrotas × 20.'))}}else detail.append(E('p','','Complete uma jornada para revelar os detalhes do seu recorde.'));layout.append(detail);content.append(layout);panel.append(content);const foot=E('footer','stream-score-foot');foot.append(E('small','','Salvo neste navegador · Campanha e Torre mantêm classificações separadas'));const back=E('button','','Voltar à biblioteca');back.onclick=close;foot.append(back);panel.append(foot)
 }
 document.addEventListener('oakchess:open-scores',e=>{e.stopImmediatePropagation();open(e.detail?.mode)},true);overlay.onclick=e=>{if(e.target===overlay)close()};window.addEventListener('keydown',e=>{if(overlay.hidden)return;e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const all=[...panel.querySelectorAll('button,select')],first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}},true);
})();
